{
  "scenario_id": "sc-3c83fd",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "CI",
      "years": [
        2017,
        2019
      ],
      "pattern": "drift",
      "direction": "decrease",
      "magnitude": "CI A/E fell from 1.098 in 2016 to 0.731 by 2019, about -0.37 cumulative and roughly -0.12 to -0.17 per year; it then abruptly returned to 1.067 in 2020 and remained around 1.05-1.10 through 2024.",
      "confidence": 0.85,
      "evidence": [
        "artifacts/ae_ci_by_year.csv: AE 2016=1.098, 2017=0.927, 2018=0.808, 2019=0.731, 2020=1.067, 2021=1.100, 2022=1.084, 2023=1.090, 2024=1.055.",
        "artifacts/ae_ci_by_year.csv: actual CI claims were flat at 776-802 in 2017-2019 while expected claims rose from 837 to 1097; 2020 actual jumped to 1322.",
        "Empirical A/E standard deviation is approximately 0.13, materially above the Poisson 1/sqrt(E) scale of roughly 0.02-0.04, so Poisson z-scores were not used."
      ],
      "recommended_action": "Investigate 2017-2019 CI claims recognition, diagnosis coding, and expected-rate/exposure calibration. Determine whether the 2020 reversion reflects retrospective claims, a definition change, or an expected-base correction. If 2020-2024 higher A/E is genuine, review CI pricing, reserving, and valuation assumptions; if 2017-2019 was under-recognized, assess prior-period releases and any valuation impact."
    }
  ]
}

